import{_ as a,C as s,o as n,c as i,ai as e,G as r}from"./chunks/framework.CUYGB37K.js";const x=JSON.parse('{"title":"Export","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/data-transfer/export.md","filePath":"2.0/data-transfer/export.md","lastUpdated":1779083873000}'),l={name:"2.0/data-transfer/export.md"};function p(d,t,c,g,u,h){const o=s("ImagePopup");return n(),i("div",null,[t[0]||(t[0]=e('<h1 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h1><p>Exporting data to save information in files is a common practice for data management, analysis, and sharing. This involves transferring data from a source system into a file format that is suitable for storage, future use, or sharing with others.</p><h3 id="steps-to-add-bulk-export-in-unopim" tabindex="-1">Steps to add Bulk Export in UnoPim <a class="header-anchor" href="#steps-to-add-bulk-export-in-unopim" aria-label="Permalink to &quot;Steps to add Bulk Export in UnoPim&quot;">​</a></h3><p><strong>Step 1:</strong> Go to the Admin panel of UnoPim and click on <strong>Data Transfer → Exports</strong> in the sidebar, then click the <strong>Create Export</strong> button.</p>',4)),r(o,{src:"/assets/2.0/images/data-transfer/export-listing.png",alt:"Export Listing"}),t[1]||(t[1]=e("<p><strong>Step 2:</strong> Under general configurations add the below fields.</p><ol><li><p><strong>Code -</strong> Enter the code of your Export process.</p></li><li><p><strong>Type -</strong> Kindly select the type i.e. (Products, Categories) which you want to Export.</p></li><li><p><strong>Filters -</strong> Select the format of the file <strong>(CSV, XLS, XLSX)</strong> as per your requirements from the dropdown.</p></li><li><p><strong>With Media -</strong> Enable or Disable if you need the export data with or without Media.</p></li></ol><p>Now, click on <strong>Save Export</strong> button. The profile is saved and you return to the Exports listing.</p>",3)),r(o,{src:"/assets/2.0/images/data-transfer/create-export-form.png",alt:"Create Export Form"}),t[2]||(t[2]=e('<p>The create export form has a two-panel layout:</p><ul><li><strong>General panel (left)</strong> — Code, Type (Products/Categories)</li><li><strong>Filters panel (right)</strong> — File Format (CSV/XLS/XLSX dropdown), With Media (toggle)</li></ul><p><strong>Step 3:</strong> From the export listing, click the <strong>Export</strong> action icon (play icon) on the row you want to run. This opens the execution page, which shows a summary of the export configuration:</p><ul><li><strong>Export Profile</strong> — The export code</li><li><strong>File Format</strong> — CSV, XLS, or XLSX</li><li><strong>With Media</strong> — Yes or No</li></ul><p>Click the <strong>Export Now</strong> button. UnoPim queues the job and redirects you to the <strong>Job Tracker</strong> detail view for that job.</p><h2 id="export-tracker" tabindex="-1">Export Tracker <a class="header-anchor" href="#export-tracker" aria-label="Permalink to &quot;Export Tracker&quot;">​</a></h2><p><strong>Step 4:</strong> The Job Tracker detail page shows the step pipeline in real time. Each step lights up with a green checkmark as it completes, and when the job finishes you get a success banner plus record counts and download links:</p>',7)),r(o,{src:"/assets/2.0/images/data-transfer/export-progress.png",alt:"Export detail page — step pipeline"}),t[3]||(t[3]=e('<p>The tracker shows a <strong>step pipeline</strong> with visual progress indicators:</p><table tabindex="0"><thead><tr><th>Step</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queued</strong></td><td>Job is in the queue waiting to be processed</td></tr><tr><td><strong>Validating</strong></td><td>Export configuration is being validated</td></tr><tr><td><strong>Exporting</strong></td><td>Records are being written to the export file</td></tr><tr><td><strong>Complete</strong></td><td>Export finished successfully</td></tr></tbody></table><p>Each step shows a green checkmark when completed. Below the pipeline you can see:</p><ul><li><strong>Success message</strong> — &quot;Job completed successfully&quot; with the total duration</li><li><strong>Records Created / Updated / Deleted</strong> — Exact counts of records exported</li><li><strong>Total Duration</strong> — How long the export took</li><li><strong>Download log</strong> — Download the full export log file</li><li><strong>Download Exported Files</strong> button — Click to download the generated file</li></ul><h3 id="pause-resume-and-cancel-controls" tabindex="-1">Pause, Resume, and Cancel Controls <a class="header-anchor" href="#pause-resume-and-cancel-controls" aria-label="Permalink to &quot;Pause, Resume, and Cancel Controls&quot;">​</a></h3><p>During an active export, <strong>job control buttons</strong> appear in the tracker:</p><ul><li><strong>Pause</strong> — Temporarily halt an in-progress export. The job state is preserved.</li><li><strong>Resume</strong> — Continue a paused export from where it left off.</li><li><strong>Cancel</strong> — Stop an export entirely. Cancelled jobs cannot be resumed.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The pause and resume feature is especially useful for large exports. You can pause a job during peak hours and resume it during off-peak times.</p></div><h2 id="quick-product-export" tabindex="-1">Quick Product Export <a class="header-anchor" href="#quick-product-export" aria-label="Permalink to &quot;Quick Product Export&quot;">​</a></h2><p>UnoPim supports <strong>dynamic management of quick product export jobs</strong>. You can quickly export selected products directly from the product listing:</p><ol><li>Navigate to <strong>Catalog → Products</strong></li><li>Select the products you want to export (or export all)</li><li>Click on <strong>Quick Export</strong> button in the top-right</li><li>Choose the format (CSV, XLS, XLSX)</li><li>The export will be processed and downloaded</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For large exports, the system uses an <strong>optimized export pipeline</strong> with eager loading and increased batch size (up to 200) for better performance. Category exports have been optimized to avoid memory overload.</p></div><p>So by the above steps you can easily create Export Data in UnoPim.</p>',13))])}const f=a(l,[["render",p]]);export{x as __pageData,f as default};
